// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    Wallet c;

    function setUp() public {
        c = new Wallet();
    }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        amount = bound(amount, 1, type(uint128).max);

        // actor deposits `amount`, funding the contract
        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();
        uint256 balanceBefore = address(c).balance;

        // actor withdraws it back
        vm.prank(actor);
        c.withdraw(amount);

        // general rule: a completed withdraw transfers the amount out of c
        assertTrue(address(c).balance == balanceBefore - amount);
    }
}
